import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

// Create axios instance with auth header
const api = axios.create({
  baseURL: "http://localhost:8001",
});

// Add interceptor to include token in requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function OCRPage() {
  const navigate = useNavigate();
  const [selectedFile, setSelectedFile] = useState(null);
  const [extractedText, setExtractedText] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [message, setMessage] = useState("");
  const [profile, setProfile] = useState(null);
  const [dragActive, setDragActive] = useState(false);

  // Check authentication on component mount
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
      return;
    }
    
    // Fetch user profile to verify token is still valid
    fetchProfile();
  }, [navigate]);

  const fetchProfile = async () => {
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        // Token expired or invalid
        localStorage.removeItem("token");
        navigate("/login");
      }
    }
  };

  const showMessage = (msg, isError = false) => {
    setMessage(msg);
    setTimeout(() => setMessage(""), isError ? 7000 : 5000);
  };

  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    validateAndSetFile(file);
  };

  const validateAndSetFile = (file) => {
    if (!file) return;

    // Check file type
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/bmp', 'image/tiff', 'image/gif', 'application/pdf'];
    if (!allowedTypes.includes(file.type)) {
      showMessage("Please select a valid image file (JPG, PNG, BMP, TIFF, GIF) or PDF.", true);
      return;
    }

    // Check file size (max 10MB)
    const maxSize = 10 * 1024 * 1024; // 10MB
    if (file.size > maxSize) {
      showMessage("File size must be less than 10MB.", true);
      return;
    }

    setSelectedFile(file);
    setExtractedText(""); // Clear previous results
    setMessage("");
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      validateAndSetFile(e.dataTransfer.files[0]);
    }
  };

  const processFile = async () => {
    if (!selectedFile) {
      showMessage("Please select a file first.", true);
      return;
    }

    setIsProcessing(true);
    setMessage("");

    try {
      const formData = new FormData();
      formData.append("file", selectedFile);

      const response = await api.post("/ocr/extract-text", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
        timeout: 60000, // 60 second timeout for OCR processing
      });

      const result = response.data;

      if (result.success) {
        setExtractedText(result.text);
        showMessage(`Text extracted successfully from ${result.filename}!`);
      } else {
        showMessage(result.error || "Failed to extract text from the file.", true);
        setExtractedText("");
      }
    } catch (err) {
      console.error("OCR processing error:", err);
      if (err.response?.status === 401) {
        localStorage.removeItem("token");
        navigate("/login");
      } else if (err.code === 'ECONNABORTED') {
        showMessage("Processing timeout. Please try with a smaller file or better quality image.", true);
      } else {
        showMessage(err.response?.data?.detail || "Error processing file. Please try again.", true);
      }
      setExtractedText("");
    } finally {
      setIsProcessing(false);
    }
  };

  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(extractedText);
      showMessage("Text copied to clipboard!");
    } catch (err) {
      console.error("Failed to copy text:", err);
      showMessage("Failed to copy text to clipboard.", true);
    }
  };

  const clearResults = () => {
    setSelectedFile(null);
    setExtractedText("");
    setMessage("");
    // Reset file input
    const fileInput = document.getElementById("file-input");
    if (fileInput) fileInput.value = "";
  };

  const logout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const goToProfile = () => {
    navigate("/profile");
  };

  // Loading spinner component
  const LoadingSpinner = () => (
    <div className="loading-spinner">
      <div className="spinner"></div>
    </div>
  );

  // Get message class based on content
  const getMessageClass = () => {
    if (!message) return "";
    return message.toLowerCase().includes("error") || message.toLowerCase().includes("failed") || message.toLowerCase().includes("timeout")
      ? "message error" 
      : "message success";
  };

  return (
    <div className="container">
      {/* Header */}
      <div className="ocr-header">
        <h1 className="app-title">OCR Text Extractor</h1>
        <div className="user-info-header">
          {profile && (
            <span className="welcome-text">
              Welcome, {profile.name || profile.username || profile.email}!
            </span>
          )}
          <div className="header-buttons">
            <button className="btn btn-secondary" onClick={goToProfile}>
              Profile
            </button>
            <button className="btn btn-danger" onClick={logout}>
              Logout
            </button>
          </div>
        </div>
      </div>

      {/* File Upload Section */}
      <div className="ocr-section">
        <h2>Upload Image or PDF</h2>
        <p className="section-description">
          Upload an image (JPG, PNG, BMP, TIFF, GIF) or PDF file to extract text using OCR technology.
        </p>

        {/* Drag and Drop Area */}
        <div
          className={`file-drop-area ${dragActive ? "drag-active" : ""}`}
          onDragEnter={handleDrag}
          onDragLeave={handleDrag}
          onDragOver={handleDrag}
          onDrop={handleDrop}
        >
          <div className="file-drop-content">
            <div className="file-icon">📁</div>
            <p>Drag and drop your file here, or</p>
            <label htmlFor="file-input" className="btn btn-primary file-select-btn">
              Choose File
            </label>
            <input
              id="file-input"
              type="file"
              accept=".jpg,.jpeg,.png,.bmp,.tiff,.gif,.pdf"
              onChange={handleFileSelect}
              style={{ display: "none" }}
            />
          </div>
        </div>

        {/* Selected File Info */}
        {selectedFile && (
          <div className="selected-file-info">
            <div className="file-details">
              <strong>Selected File:</strong> {selectedFile.name}
              <br />
              <strong>Size:</strong> {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
              <br />
              <strong>Type:</strong> {selectedFile.type}
            </div>
            <div className="file-actions">
              <button
                className="btn btn-primary"
                onClick={processFile}
                disabled={isProcessing}
              >
                {isProcessing ? (
                  <>
                    <LoadingSpinner />
                    Processing...
                  </>
                ) : (
                  "Extract Text"
                )}
              </button>
              <button className="btn btn-secondary" onClick={clearResults}>
                Clear
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Results Section */}
      {extractedText && (
        <div className="ocr-section">
          <h2>Extracted Text</h2>
          <div className="results-container">
            <div className="results-header">
              <span className="results-info">
                {extractedText.length} characters extracted
              </span>
              <button className="btn btn-secondary copy-btn" onClick={copyToClipboard}>
                📋 Copy Text
              </button>
            </div>
            <div className="extracted-text">
              {extractedText}
            </div>
          </div>
        </div>
      )}

      {/* Processing Indicator */}
      {isProcessing && (
        <div className="processing-overlay">
          <div className="processing-content">
            <LoadingSpinner />
            <h3>Processing your file...</h3>
            <p>This may take a few moments depending on file size and complexity.</p>
          </div>
        </div>
      )}

      {/* Message Display */}
      {message && <div className={getMessageClass()}>{message}</div>}

      {/* Instructions */}
      <div className="ocr-section instructions">
        <h3>Tips for Better Results</h3>
        <ul>
          <li>Use high-resolution images with clear, readable text</li>
          <li>Ensure good contrast between text and background</li>
          <li>Avoid blurry or skewed images</li>
          <li>For PDFs, text-based PDFs work better than scanned images</li>
          <li>Maximum file size: 10MB</li>
        </ul>
      </div>
    </div>
  );
}

export default OCRPage;
